int nvgpu_get_mock_reglist_ga10b(struct gk20a *g, u32 reg_idx,
			   struct nvgpu_mock_iospace *iospace)
{
	(void)g;
	int err = 0;

#ifndef NVGPU_MON_PRESENT
	switch (reg_idx) {
	case MOCK_REGS_FB:
		iospace->base = 0x100000;
		iospace->size = 0xFAC00;
		iospace->data = NULL;
		break;
	case MOCK_REGS_GR:
		iospace->data = nvgpu_ga10b_gr_regs;
		iospace->size = sizeof(nvgpu_ga10b_gr_regs);
		iospace->base = 0x400000;
		break;
	case MOCK_REGS_FUSE:
		iospace->data = nvgpu_ga10b_fuse_regs;
		iospace->size = sizeof(nvgpu_ga10b_fuse_regs);
		iospace->base = 0x00820000;
		break;
	case MOCK_REGS_MASTER:
		iospace->data = nvgpu_ga10b_master_regs;
		iospace->size = sizeof(nvgpu_ga10b_master_regs);
		iospace->base = 0x0;
		break;
	case MOCK_REGS_TOP:
		iospace->data = nvgpu_ga10b_top_regs;
		iospace->size = sizeof(nvgpu_ga10b_top_regs);
		iospace->base = 0x22400;
		break;
	case MOCK_REGS_FIFO:
		break;
	case MOCK_REGS_PRI:
		iospace->data = nvgpu_ga10b_pri_regs;
		iospace->size = sizeof(nvgpu_ga10b_pri_regs);
		iospace->base = 0x120000;
		break;
	case MOCK_REGS_PBDMA:
		iospace->data = nvgpu_ga10b_pbdma_regs;
		iospace->size = sizeof(nvgpu_ga10b_pbdma_regs);
		iospace->base = 0x40000;
		break;
	case MOCK_REGS_CCSR:
		err = -EINVAL;
		break;
	case MOCK_REGS_USERMODE:
		iospace->data = NULL;
		iospace->size = 0x10000;
		iospace->base = 0x30000;
		break;
	case MOCK_REGS_RUNLIST1:
		iospace->data = nvgpu_ga10b_runlist_engine1_regs;
		iospace->size = sizeof(nvgpu_ga10b_runlist_engine1_regs);
		iospace->base = 0x00C00000;
		break;
	case MOCK_REGS_RUNLIST2:
		iospace->data = nvgpu_ga10b_runlist_engine2_regs;
		iospace->size = sizeof(nvgpu_ga10b_runlist_engine2_regs);
		iospace->base = 0x00C00400;
		break;
	case MOCK_REGS_RUNLIST3:
		iospace->data = nvgpu_ga10b_runlist_engine3_regs;
		iospace->size = sizeof(nvgpu_ga10b_runlist_engine3_regs);
		iospace->base = 0x00C00800;
		break;
	case MOCK_REGS_RUNLIST4:
		iospace->data = nvgpu_ga10b_runlist_engine4_regs;
		iospace->size = sizeof(nvgpu_ga10b_runlist_engine4_regs);
		iospace->base = 0x00C00C00;
		break;
	case MOCK_REGS_CHRAM1:
		iospace->data = nvgpu_ga10b_chram_engine1_regs;
		iospace->size = sizeof(nvgpu_ga10b_chram_engine1_regs);
		iospace->base = 0x00C20000;
		break;
	case MOCK_REGS_CHRAM2:
		iospace->data = nvgpu_ga10b_chram_engine2_regs;
		iospace->size = sizeof(nvgpu_ga10b_chram_engine2_regs);
		iospace->base = 0x00C22000;
		break;
	case MOCK_REGS_CHRAM3:
		iospace->data = nvgpu_ga10b_chram_engine3_regs;
		iospace->size = sizeof(nvgpu_ga10b_chram_engine3_regs);
		iospace->base = 0x00C24000;
		break;
	case MOCK_REGS_CHRAM4:
		iospace->data = nvgpu_ga10b_chram_engine4_regs;
		iospace->size = sizeof(nvgpu_ga10b_chram_engine4_regs);
		iospace->base = 0x00C26000;
		break;
	case MOCK_REGS_LTC:
		iospace->base = 0x140000;
		iospace->size = sizeof(nvgpu_ga10b_ltc_regs);
		iospace->data = nvgpu_ga10b_ltc_regs;
		break;
	case MOCK_REGS_PGSP:
		iospace->base = 0x110000;
		iospace->size = sizeof(nvgpu_ga10b_pgsp_regs);
		iospace->data = nvgpu_ga10b_pgsp_regs;
		break;
	case MOCK_REGS_FUNC:
		iospace->base = 0xB80000;
		iospace->size = sizeof(nvgpu_ga10b_func_regs);
		iospace->data = nvgpu_ga10b_func_regs;
		break;
	case MOCK_REGS_CE:
		iospace->base = 0x104000;
		iospace->size = sizeof(nvgpu_ga10b_ce_regs);
		iospace->data = nvgpu_ga10b_ce_regs;
		break;
	case MOCK_REGS_PBUS:
		iospace->base = 0x1000;
		iospace->size = sizeof(nvgpu_ga10b_pbus_regs);
		iospace->data = nvgpu_ga10b_pbus_regs;
		break;
	case MOCK_REGS_HSHUB:
		iospace->base = 0x00004000;
		iospace->size = 0x1000;
		iospace->data = NULL;
		break;
	case MOCK_REGS_CTRL:
		iospace->base = 0xb60000;
		iospace->size = 0x10000;
		iospace->data = NULL;
		break;
	default:
		err = -EINVAL;
		break;
	}
#else
	switch (reg_idx) {
	case MOCK_REGS_GR:
		iospace->data = nvgpu_ga10b_gr_regs;
		iospace->size = sizeof(nvgpu_ga10b_gr_regs);
		iospace->base = 0x400000;
		break;
		break;
	case MOCK_REGS_MASTER:
		iospace->data = nvgpu_ga10b_master_regs;
		iospace->size = sizeof(nvgpu_ga10b_master_regs);
		iospace->base = 0x0;
		break;
	case MOCK_REGS_PRI:
		iospace->data = nvgpu_ga10b_pri_regs;
		iospace->size = sizeof(nvgpu_ga10b_pri_regs);
		iospace->base = 0x120000;
		break;
	case MOCK_REGS_LTC:
		iospace->base = 0x140000;
		iospace->size = sizeof(nvgpu_ga10b_ltc_regs);
		iospace->data = nvgpu_ga10b_ltc_regs;
		break;
	case MOCK_REGS_PGSP:
		iospace->base = 0x110000;
		iospace->size = sizeof(nvgpu_ga10b_pgsp_regs);
		iospace->data = nvgpu_ga10b_pgsp_regs;
		break;
	case MOCK_REGS_FUNC:
		iospace->base = 0xB80000;
		iospace->size = sizeof(nvgpu_ga10b_func_regs);
		iospace->data = nvgpu_ga10b_func_regs;
		break;
	default:
		err = -EINVAL;
		break;
	}
#endif

	return err;
}
